function Show-List([string]"'$name) {
  $m = [regex]::Match($txt, [regex]::Escape($name) + '"': \\[(["'^'"\\]]*)\\]')
  if (-not "'$m.Success) { Write-Output "$name NOT FOUND"; return }
  $items = @($m.Groups[1].Value -split '"',' | ForEach-Object { "'$_.Trim() } | Where-Object { $_ })
  Write-Output "$name count=$($items.Count)"
  foreach ($pkg in @('"'com.bilibili.app.in','tv.danmaku.bili','com.netease.cloudmusic','com.hihonor.cloudmusic','com.hihonor.iaware','com.hihonor.phoneservice','com.hihonor.android.FloatTasks','com.hihonor.hndockbar','com.hihonor.hiboard')) {
    Write-Output (\"  {0}={1}\" -f "'$pkg, ($items -contains $pkg))
  }
}
